INSERT INTO `xy_index_msg` VALUES (1,'平台公告','Platform announcemen','Platform announcemen','Platform announcemen','Platform announcemen','<pre data-placeholder=\"คำแปล\" dir=\"ltr\" id=\"tw-target-text\">\r\nเรียนสมาชิก สวัสดี! เกี่ยวกับบัตรโอน มีปัญหาในการควบคุมความเสี่ยงในการโอนจากระยะไกล เนื่องจาก  เหรียญUSDT  เป็นซอฟต์แวร์การชำระเงินของบุคคลที่สาม กระทรวงข้อมูลสาธารณะจึงมีหน้าที่ป้องกันการฟอกเงิน ปัญหาดังกล่าวเป็นเรื่องปกติ โปรดอย่ากังวล ขอแนะนำให้คุณใช้กระเป๋าเงิน bitcoin เติมเงินกระเป๋าเงิน USDT  ง่ายและรวดเร็ว ขอให้คุณมีความสุขในชีวิต!</pre>','<p>เรียนสมาชิก สวัสดี! เกี่ยวกับบัตรโอน มีปัญหาในการควบคุมความเสี่ยงในการโอนจากระยะไกล เนื่องจาก เหรียญUSDT เป็นซอฟต์แวร์การชำระเงินของบุคคลที่สาม กระทรวงข้อมูลสาธารณะจึงมีหน้าที่ป้องกันการฟอกเงิน ปัญหาดังกล่าวเป็นเรื่องปกติ โปรดอย่ากังวล ขอแนะนำให้คุณใช้กระเป๋าเงิน bitcoin เติมเงินกระเป๋าเงิน USDT ง่ายและรวดเร็ว ขอให้คุณมีความสุขในชีวิต!</p>','<p>เรียนสมาชิก สวัสดี! เกี่ยวกับบัตรโอน มีปัญหาในการควบคุมความเสี่ยงในการโอนจากระยะไกล เนื่องจาก เหรียญUSDT เป็นซอฟต์แวร์การชำระเงินของบุคคลที่สาม กระทรวงข้อมูลสาธารณะจึงมีหน้าที่ป้องกันการฟอกเงิน ปัญหาดังกล่าวเป็นเรื่องปกติ โปรดอย่ากังวล ขอแนะนำให้คุณใช้กระเป๋าเงิน bitcoin เติมเงินกระเป๋าเงิน USDT ง่ายและรวดเร็ว ขอให้คุณมีความสุขในชีวิต!</p>','<p>เรียนสมาชิก สวัสดี! เกี่ยวกับบัตรโอน มีปัญหาในการควบคุมความเสี่ยงในการโอนจากระยะไกล เนื่องจาก เหรียญUSDT เป็นซอฟต์แวร์การชำระเงินของบุคคลที่สาม กระทรวงข้อมูลสาธารณะจึงมีหน้าที่ป้องกันการฟอกเงิน ปัญหาดังกล่าวเป็นเรื่องปกติ โปรดอย่ากังวล ขอแนะนำให้คุณใช้กระเป๋าเงิน bitcoin เติมเงินกระเป๋าเงิน USDT ง่ายและรวดเร็ว ขอให้คุณมีความสุขในชีวิต!</p>','<p>เรียนสมาชิก สวัสดี! เกี่ยวกับบัตรโอน มีปัญหาในการควบคุมความเสี่ยงในการโอนจากระยะไกล เนื่องจาก เหรียญUSDT เป็นซอฟต์แวร์การชำระเงินของบุคคลที่สาม กระทรวงข้อมูลสาธารณะจึงมีหน้าที่ป้องกันการฟอกเงิน ปัญหาดังกล่าวเป็นเรื่องปกติ โปรดอย่ากังวล ขอแนะนำให้คุณใช้กระเป๋าเงิน bitcoin เติมเงินกระเป๋าเงิน USDT ง่ายและรวดเร็ว ขอให้คุณมีความสุขในชีวิต!</p>',3,1647762641,1,'admin','平台公告','<p>เรียนสมาชิก สวัสดี! เกี่ยวกับบัตรโอน มีปัญหาในการควบคุมความเสี่ยงในการโอนจากระยะไกล เนื่องจาก เหรียญUSDT เป็นซอฟต์แวร์การชำระเงินของบุคคลที่สาม กระทรวงข้อมูลสาธารณะจึงมีหน้าที่ป้องกันการฟอกเงิน ปัญหาดังกล่าวเป็นเรื่องปกติ โปรดอย่ากังวล ขอแนะนำให้คุณใช้กระเป๋าเงิน bitcoin เติมเงินกระเป๋าเงิน USDT ง่ายและรวดเร็ว ขอให้คุณมีความสุขในชีวิต!</p>','プラットフォームの発表','<p>เรียนสมาชิก สวัสดี! เกี่ยวกับบัตรโอน มีปัญหาในการควบคุมความเสี่ยงในการโอนจากระยะไกล เนื่องจาก เหรียญUSDT เป็นซอฟต์แวร์การชำระเงินของบุคคลที่สาม กระทรวงข้อมูลสาธารณะจึงมีหน้าที่ป้องกันการฟอกเงิน ปัญหาดังกล่าวเป็นเรื่องปกติ โปรดอย่ากังวล ขอแนะนำให้คุณใช้กระเป๋าเงิน bitcoin เติมเงินกระเป๋าเงิน USDT ง่ายและรวดเร็ว ขอให้คุณมีความสุขในชีวิต!</p>'),(2,'平台简介','company profile ','Profil de la société','Perfil de la empresa','perfil de companhia','<p>温馨提示：同一个人银行卡信息请勿重复注册抢单，经发现将会冻结账号ID.</p>\r\n\r\n<p>个人多账户代还会导致持卡人信用卡降低额度，影响持卡人信用卡的信誉度，导致平台持卡人签订的代还信用卡违约与合同条约，请各位兼职会员勿使用个人多账号，一卡绑定多账户被系统检测到将会永久封号！</p>\r\n\r\n<p>常见问题：</p>\r\n\r\n<p>1.关于充值</p>\r\n\r\n<p>充值在&ldquo;我的&rdquo;--&ldquo;我立即充值&rdquo;界面进行充值。点击&ldquo;确定&rdquo;按钮，输入充值金额，点击银行卡转账。按照平台提供的账户汇款后,务必提交转账到账成功截图,然后点击&ldquo;提交&rdquo;即可。为保证充值快速到账，烦请您所填转账人姓名和汇款金额一定要和汇款时的一致。如在充值过程中遇到无法解决的问题,请及时联系人工客服。由于充值信息量过大，充值前请务必仔细核对本平台的账户卡号，本平台不定期更换账号，每一次的充值都需要跟客服获取商家卡号，充错卡号不予在平台上充值，后果自行负责，有不明白的问题可以咨询在线客服！</p>\r\n\r\n<p>2.关于提现</p>\r\n\r\n<p>在提现之前，烦请您先在APP绑定您的提现信息。在平台工作时间内，可在&ldquo;我的&rdquo;--&ldquo;我的钱包&rdquo;界面进行提现。点击&ldquo;提现&rdquo;按钮，输入您想要提现的金额和提现密码就可进行提现。21:00点之前提现都是0-15分钟到账，繁忙高峰期30分钟内到账，21:00点以后提现次日到账！</p>\r\n\r\n<p>3.关于代还</p>\r\n\r\n<p>在APP内完善好个人真实资料，客户需绑定自己可以接受短信开通手机银行的银行卡，方便查收款项和对商家卡号进行转账！已经充值到账后，即可进行抢单，在抢单成功后系统会根据客户的会员等级不同匹配的时间和金额也会不同，具体参考会员等级！正常会员系统会在15-20分钟内匹配代还订单！</p>\r\n\r\n<p>4.关于订单冻结</p>\r\n\r\n<p>平台都是根据客户的账户金额和云数据匹配相对应的代还信用卡订单，偶尔订单会出现大过账户本金的情况，不属于福利订单，客户只需补全负数，系统就可第一时间为您结算，订单未完成24小时后将会被系统自动冻结账户，30个工作日内自动解冻，返回您充值的金额到您的账户上！未能理解的可以咨询在线客服！（注：若账户出现福利订单任务未及时处理，系统将视为不作处理，依法冻结账户本金，并且扣除违约金来处理，如有疑问请联系在线客服咨询）</p>\r\n\r\n<p>5.关于代理</p>\r\n\r\n<p>平台用户推荐新人即可成为平台代理，同时可以获得额外的动态奖励，直推一级用户奖励为一级用户每天所得佣金的16%，二级用户奖励为二级用户每天所得佣金的8%，三级用户奖励为三级用户每天所得佣金的4%。</p>\r\n\r\n<p>6.抢单时间</p>\r\n\r\n<p>平台运营时间为每天09:00-21:00，用户在平台运营时间内都可进行抢单。</p>\r\n\r\n<p>本协议阐述只条款和条件适用于您实用本网站所提供的各种工具和服务（下称&ldquo;服务&rdquo;）<br />\r\n一、接受条款<br />\r\n通过《嘉德》或APP进入即表示您同意自己已经与《嘉德》公司订立本协议，且您将受本协议的条款和条件 (&ldquo;条款&rdquo;) 约束。公司可随时自行全权决定更改&ldquo;条款&rdquo;。如您不同意相关变更，必须停止使用&ldquo;服务&rdquo;。经修订的&ldquo;条款&rdquo;一经网站公布，立即自动生效。您应在第一次登录后仔细阅读修订后的&ldquo;条款&rdquo;，并有权选择停止继续使用&ldquo;服务&rdquo;；一旦您继续使用&ldquo;服务&rdquo;，则表示您已接受经修订的&ldquo;条款&rdquo;，当您与公司发生争议时，应以最新的服务协议为准。除另行明确声明外，任何使&ldquo;服务&rdquo;范围扩大或功能增强的新内容均受本协议约束。除非经公司的授权高层管理人员签订书面协议，本协议不得另行作出修订。</p>\r\n\r\n<p>二、谁可使用本网站<br />\r\n&ldquo;嘉德&rdquo;仅供能够根据相关法律订立具有法律约束力的合约的个人或公司使用。因此，您的年龄必须在十八周岁或以上，才可使用本公司服务。如不符合本项条件，请勿使用&ldquo;随心选&rdquo;。公司可随时自行全权决定拒绝向任何人士提供&ldquo;嘉德&rdquo;。&ldquo;随心选&rdquo;不会提供给被暂时或永久中止资格的会员。</p>\r\n\r\n<p>三、收费<br />\r\n本公司承诺不会收取平台用户的任何费用，无需押金，无需保证金，并且不会以任何方式联系用户索要任何费用，本公司联系方式请认准在线客服。用户需要自行充值到平台里面，方可进行代购。</p>\r\n\r\n<p>四、您的资料和提供买卖的物品<br />\r\n&ldquo;您的资料&rdquo;包括您在注册、交易或列举物品过程中、在任何公开信息场合或通过任何电子邮件形式，向本公司或其他用户提供的任何资料，包括数据、文本、软件、音乐、声响、照片、图画、影像、词句或其他材料。您应对&ldquo;您的资料&rdquo;真实性负全部责任，而本公司仅作为您在网上发布和刊登&ldquo;您的资料&rdquo;的被动渠道。但是，倘若本公司认为您的信息，可能使本公司承担任何法律或道义上的责任，或可能使本公司 (全部或部分地) 失去本公司的互联网服务供应商或其他供应商的服务，或您未在公司规定的期限内登录或再次登录网站，则本公司可自行全权决定对您的信息采取本公司认为必要或适当的任何行动，包括但不限于删除该类资料。您特此保证，您对提交给资料拥有全部权利，包括全部版权。您确认，网站没有责任去认定或决定您提交给本公司的信息哪些是应当受到保护的，对享有&ldquo;服务&rdquo;的其他用户使用您的信息，本公司也不必负责。</p>\r\n\r\n<p>五、注册义务<br />\r\n如您在公司网站注册，您必须同意：</p>\r\n\r\n<p>（一）根据公司网址所刊载的会员信息表格的要求，提供关于您或贵公司的真实、准确、完整和反映当前情况的信息；</p>\r\n\r\n<p>（二）维持并及时更新会员资料，使其保持真实、准确、完整和反映当前情况。倘若您提供任何不真实、不准确、不完整或不能反映当前情况的信息，或公司有合理理由怀疑该类资料不真实、不准确、不完整或不能反映当前情况的，公司有权暂停或终止您的注册身份及信息，并拒绝您在目前或将来对&ldquo;服务&rdquo;(或其任何部份)何形式使用。如您代表一家公司或其他法律主体在本公司登记，则您必须声明和保证，您有权使该公司或其他法律主体受本协议&ldquo;条款&rdquo;约束。</p>\r\n\r\n<p>六、会员注册名、密码和保密<br />\r\n登记过程中，您将选择会员注册名和密码。您须自行负责对您的会员注册名和密码保密，且须对您在会员注册名和密码下发生的所有活动承担责任。您同意：</p>\r\n\r\n<p>（一）如发现任何人未经授权使用您的会员注册名或密码，或发生违反保密规定的任何其他情况，您会立即通知公司；</p>\r\n\r\n<p>（二）确保您在每个上网时段结束时，以正确步骤离开网站。网站不能也不会对因您未能遵守本款规定而发生的任何损失或损毁负责。</p>\r\n\r\n<p>七、关于您的信息的规则<br />\r\n您同意，您的个人信息和您提供在公司网站上交易的任何&ldquo;资料&rdquo;（泛指一切可供依法交易的、有形的或无形的、以各种形态存在的某种具体的物品，或某种权利或利益，或某种票据或证券，或某种服务或行为。本协议中&ldquo;物品&rdquo;一词均含此义）：</p>\r\n\r\n<p>（一）不会有欺诈成份，与售卖伪造或盗窃无涉；</p>\r\n\r\n<p>（二）不会侵犯任何第三者对该物品享有的物权，或版权、专利、商标、商业秘密或其他知识产权、隐私权、名誉权；</p>\r\n\r\n<p>（三）不会违反任何法律、法规、条例或规章 (包括但不限于关于规范出口管理、贸易配额、保护消费者、不正当竞争或虚假广告的法律、法规、条例或规章)；</p>\r\n\r\n<p>（四）不会含有诽谤（包括商业诽谤）、非法恐吓或非法骚扰的内容；</p>\r\n\r\n<p>（五）不会含有淫秽、或包含任何儿童色情内容；</p>\r\n\r\n<p>（六）不会含有蓄意毁坏、恶意干扰、秘密地截取或侵占任何系统、数据或个人资料的任何病毒、伪装破坏程序、电脑蠕虫、定时程序炸弹或其他电脑程序；</p>\r\n\r\n<p>（七）不会直接或间接与下述各项货物或服务连接，或包含对下述各项货物或服务的描述：１. 本协议项下禁止的货物或服务；２. 您无权连接或包含的货物或服务；</p>\r\n\r\n<p>（八）不会含有诽谤（包括商业诽谤）、非法恐吓或非法骚扰的内容；</p>\r\n\r\n<p>（九）不会在与任何连锁信件、大量胡乱邮寄的电子邮件、滥发电子邮件或任何复制或多余的信息有关的方面使用&ldquo;服务&rdquo;；</p>\r\n\r\n<p>（十）不会未经其他人士同意，利用&ldquo;服务&rdquo;收集其他人士的电子邮件地址及其他信息；</p>\r\n\r\n<p>（十一）不会利用&ldquo;服务&rdquo;制作虚假的电子邮件地址，或以其他形式试图在发送人的身份或信息的来源方面误导其他人士。</p>\r\n\r\n<p>八、被禁止物品<br />\r\n您不得在本公司网站公布或通过本公司网站买卖：</p>\r\n\r\n<p>（一）可能使本公司违反任何相关法律、法规、条例或规章的任何物品；</p>\r\n\r\n<p>（二）公司认为应禁止或不适合通过本网站买卖的任何物品。</p>\r\n\r\n<p>九、您授予本公司的许可使用权<br />\r\n您授予本公司独家的、全球通用的、永久的、免费的许可使用权利 (并有权在多个层面对该权利进行再授权)，使本公司有权(全部或部份地) 使用、复制、修订、改写、发布、翻译、分发、执行和展示&ldquo;您的资料&rdquo;或制作其派生作品，和/或以现在已知或日后开发的任何形式、媒体或技术，将&ldquo;您的资料&rdquo;纳入其他作品内。</p>\r\n\r\n<p>十、隐私<br />\r\n尽管有第九条所规定的许可使用权，我们将仅根据本公司的隐私声明使用你提供的信息。本公司隐私声明的全部条款属于本协议的一部份，因此，您必须仔细阅读。请注意，您一旦自愿地在公司网站披露您的信息，该类资料即可能被其他人士获取和使用。</p>\r\n\r\n<p>十一、终止或访问限制<br />\r\n您同意，在公司未向您收费的情况下，本公司可自行全权决定以任何理由 (包括但不限于公司认为您已违反本协议的字面意义和精神，或您以不符合本协议的字面意义和精神的方式行事，或您在超过90天的时间内未以您的帐号及密码登录网站) 终止您的&ldquo;服务&rdquo;密码、帐户 (或其任何部份) 或您对&ldquo;服务&rdquo;的使用，并删除和丢弃您在使用&ldquo;服务&rdquo;中提交的 信息。您同意，在公司向您收费的情况下，公司应基于合理的怀疑且经电子邮件通知的情况下实施上述终止服务的行为。公司同时可自行全权决定，在发出通知或不发出通知的情况下，随时停止提供&ldquo;服务&rdquo;或其任何部份。您同意，根据本协议的任何规定终止您使用&ldquo;服务&rdquo;之措施可在不发出事先通知的情况下实施，并承认和同意，公司可立即使您的帐户无效，或撤销您的帐户以及在您的帐户内的所有相关资料和档案，和/或禁止您进一步接入该等档案或&ldquo;服务&rdquo;。帐号终止后，公司没有义务为您保留原帐号中或与之相关的任何信息，或转发任何未曾阅读或发送的信息给您或第三方。此外，您同意，公司不会就终止您接入&ldquo;服务&rdquo;而对您或任何第三者承担任何责任。第12、13、14和22条应在本协议终止后继续有效。</p>\r\n\r\n<p>十二、违反规则会有什么后果？<br />\r\n在不限制其他补救措施的前提下，发生下述任一情况，本公司可立即发出警告，暂时终止、永久终止或终止您的会员资格，删除您的任何现有产品信息，以及您在网站上展示的任何其他资料：</p>\r\n\r\n<p>（一）您违反本协议</p>\r\n\r\n<p>（二）本公司无法核实或鉴定您向本公司提供的任何资料</p>\r\n\r\n<p>（三）本公司相信您的行为可能会使您、本公司用户或通过本公司或本公司网站提供服务的第三者服务供应商发生任何法律责任。在不限制任何其他补救措施的前提下，倘若发现您从事涉及本公司网站的诈骗活动，公司可暂停或终止您的帐户。</p>\r\n\r\n<p>十三、服务&ldquo;嘉德&rdquo;提供<br />\r\n本公司会尽一切努力使您在使用公司网站的过程中得到乐趣。遗憾的是，本公司不能随时预见到任何技术上的问题或其他困难。该等困难可能会导致数据损失或其他服务中断。为此，您明确理解和同意，您使用&ldquo;服务&rdquo;的风险由您自行承担。&ldquo;服务&rdquo;以&ldquo;按现状&rdquo;和&ldquo;按可得到&rdquo;的基础提供。公司明确声明不作出任何种类的所有明示或暗示的保证，包括但不限于关于适销性、适用于某一特定用途和无侵权行为等方面的保证。公司对下述内容不作保证：</p>\r\n\r\n<p>（一）&ldquo;服务&rdquo;会符合您的要求</p>\r\n\r\n<p>（二）&ldquo;服务&rdquo;不会中断，且适时、安全和不带任何错误</p>\r\n\r\n<p>（三）通过使用&ldquo;服务&rdquo;而可能获取的结果将是准确或可信赖的</p>\r\n\r\n<p>（四）您通过&ldquo;嘉德&rdquo;而购买或获取的任何产品、服务、资料或其他材料的质量将符合您的预期。通过使用&ldquo;服务&rdquo;而下载或以其他形式获取任何材料是由您自行全权决定进行的，且与此有关的风险由您自行承担，对于因您下载任何该等材料而发生的您的电脑系统的任何损毁或任何数据损失，您将自行承担责任。您从公司或通过或从&ldquo;嘉德&rdquo;获取的任何口头或书面意见或资料，均不产生未在本协议内明确载明的任何保证。</p>\r\n\r\n<p>十四、责任范围<br />\r\n明确理解和同意，公司不对因下述任一情况而发生的任何损害赔偿承担责任，包括但不限于利润、商誉、使用、数据等方面的损失或其他无形损失的损害赔偿 (无论公司是否已被告知该等损害赔偿的可能性)：</p>\r\n\r\n<p>（一）使用或未能使用&ldquo;嘉德&rdquo;</p>\r\n\r\n<p>（二）因通过或从&ldquo;嘉德&rdquo;购买或获取任何货物、样品、数据、资料或服务，或通过或从&ldquo;随心选&rdquo;接收任何信息或缔结任何交易所产生的获取替代货物和服务的费用；</p>\r\n\r\n<p>（三）未经批准接入或更改您的传输资料或数据</p>\r\n\r\n<p>（四）任何第三者对&ldquo;嘉德&rdquo;的声明或关于&ldquo;嘉德&rdquo;的行为</p>\r\n\r\n<p>（五）因任何原因而引起的与&ldquo;服务&rdquo;有关的任何其他事宜，包括疏忽。<br />\r\n十五、订单规则</p>\r\n\r\n<p>（一）订单有多个类型，每一类型针对人群都有所不同。</p>\r\n\r\n<p>（二）普通订单为常规订单，普通订单不会超过客户账户本金余额。平台最多2个订单统一结算，客户接取此类订单时需要注意规则。以上所有订单类型适用于个人与团队。（注：团队任务需要团队成员所有人完成任务，否则视为未完成任务）</p>\r\n\r\n<p>（三）违规者自行承担后果，包括但不限于违约金，风险金等。</p>\r\n\r\n<p>（四）促销联单和福利联单是统一完成后返款。</p>\r\n\r\n<p>（五） 福利单需要在规定的1个小时内完成。<br />\r\n（六）注：出现违规操作超时等，可能导致信用分扣除！</p>\r\n\r\n<p>十六、赔偿<br />\r\n您同意，因您违反本协议或经在此提及而纳入本协议的其他文件，或因您违反了法律或侵害了第三方的权利，而使第三方对本公司及其子公司、分公司、董事、职员、代理人提出索赔要求（包括司法费用和其他专业人士的费用），您必须赔偿给本公司及其子公司、分公司、董事、职员、代理人，使其等免遭损失。</p>\r\n\r\n<p>十七、遵守法律<br />\r\n您应遵守与您使用&ldquo;服务条款&rdquo;，以及与您提供商贸信息有关的所有相关的法律、法规、条例和规章。</p>\r\n\r\n<p>十八、代理关系<br />\r\n您与本公司仅为独立订约人关系。本协议无意结成或创设任何代理、合伙、合营、雇用与被雇用或特许权授予与被授予关系。</p>\r\n\r\n<p>十九、广告和金融服务<br />\r\n您与在&ldquo;嘉德&rdquo;上或通过&ldquo;嘉德&rdquo;物色的刊登广告人士通讯或进行业务往来或参与其推广活动，包括就相关货物或服务付款和交付相关货物或服务，以及与该等业务往来相关的任何其他条款、条件、保证或声明，仅限于在您和该刊登广告人士之间发生。您同意，对于因任何该等业务往来或因在&ldquo;服务&rdquo;上出现该等刊登广告人士而发生的任何种类的任何损失或损毁，本公司无需负责或承担任何责任。您如打算通过&ldquo;服务&rdquo;创设或参与与任何公司、股票行情、投资或证券有关的任何服务，或通过&ldquo;服务&rdquo;收取或要求与任何公司、股票行情、投资或证券有关的任何新闻信息、警戒性信息或其他资料，敬请注意，本公司不会就通过&ldquo;服务&rdquo;传送的任何该等资料的准确性、有用性或可用性、可获利性负责或承担任何责任，且不会对根据该等资料而作出的任何交易或投资决策负责或承担任何责任。</p>\r\n\r\n<p>二十、链接<br />\r\n&ldquo;嘉德&rdquo;或第三者均可提供与其他万维网网站或资源的链接。由于本网站并不控制该等网站和资源，您承认并同意，本公司并不对该等外在网站或资源的可用性负责，且不认可该等网站或资源上或可从该等网站或资源获取的任何内容、宣传、产品、服务或其他材料，也不对其等负责或承担任何责任。您进一步承认和同意，对于任何因使用或信赖从此类网站或资源上获取的此类内容、宣传、产品、服务或其他材料而造成（或声称造成）的任何直接或间接损失，本公司均不承担责任。</p>\r\n\r\n<p>二十一、其他规定<br />\r\n本协议构成您和公司之间的全部协议，规定了您对&ldquo;工艺精造&rdquo;的使用，并取代您和公司先前订立的任何书面或口头协议。本协议各方面应受中华人民共和国大陆地区法律的管辖。倘若本协议任何规定被裁定为无效或不可强制执行，该项规定应被撤销，而其余规定应予执行。条款标题仅为方便参阅而设，并不以任何方式界定、限制、解释或描述该条款的范围或限度。本公司未就您或其他人士的某项违约行为采取行动，并不表明本公司撤回就任何继后或类似的违约事件采取行动的权利。</p>\r\n\r\n<p>二十二、通知<br />\r\n除非另有明确规定，任何通知应以电子邮件形式发送，(就本公司而言) 电子邮件地址为 dovekf@acca.com.cn，或 (就您而言)发送到您在登记过程中向本公司提供的电子邮件地址，或有关方指明的该等其他地址。在电子邮件发出二十四 (24) 小时后，通知应被视为已送达，除非发送人被告知相关电子邮件地址已作废。或者，本公司可通过邮资预付挂号邮件并要求回执的方式，将通知发到您在登记过程中向我司提供的地址。在该情况下，在付邮当日三 (3) 天后通知被视为已送达。</p>\r\n\r\n<p>二十三、不可抗力<br />\r\n对于因本公司合理控制范围以外的原因，包括但不限于自然灾害、罢工或骚乱、物质短缺或定量配给、暴动、战争行为、政府行为、通讯或其他设施故障或严重伤亡事故等，致使本公司延迟或未能履约的，本公司不对您承担任何责任。</p>\r\n\r\n<p>二十四、转让<br />\r\n本公司转让本协议无需经您同意。</p>\r\n\r\n<p>二十五、其他规定<br />\r\n本协议构成您和本公司之间的全部协议，规定了您对&ldquo;服务&rdquo;的使用，并取代您和本公司先前订立的任何书面或口头协议。本协议各方面应受中华人民共和国大陆地区法律的管辖。倘若本协议任何规定被裁定为无效或不可强制执行，该项规定应被撤销，而其余规定应予执行。条款标题仅为方便参阅而设，并不以任何方式界定、限制、解释或描述该条款的范围或限度。本公司未就您或其他人士的某项违约行为采取行动，并不表明本公司撤回就任何继后或类似的违约事件采取行动的权利。</p>\r\n\r\n<p>二十六、平台提现硬性要求信用分值最低需要100分！</p>\r\n\r\n<p>温馨提示：同一个人银行卡信息请勿重复注册抢单，经发现将会冻结账号ID.</p>\r\n\r\n<p>个人多账户代购会导致商家封店，影响商家信誉度以及销量单作废，本平台禁止一卡绑定多账户，请各位兼职会员请勿使用个人多账号，一卡绑定多账户全部给与资金冻结90天账号永久封号处理！本平台为了防止有人恶意进行洗黑钱或套现一系列的不正当行为，兼职会员账户完成账户金额相对应的流水即可全额提款</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>（常见问题）</p>\r\n\r\n<p>1.关于充值</p>\r\n\r\n<p>充值在&ldquo;我的&rdquo;--&ldquo;我的钱包&rdquo;界面进行充值。点击&ldquo;充值&rdquo;按钮，<b>然后填写转账人的姓名和需转账的金额点击去转账进行汇款充值</b>。按照平台提供的账户汇款后,<b>务必提交转账到账成功截图</b>,然后点击&ldquo;提交&rdquo;即可。为保证充值快速到账，烦请您所填转账人姓名和汇款金额一定要和汇款时的一致。如在充值过程中遇到无法解决的问题,请及时联系人工客服。由于充值信息量过大，充值前请务必仔细核对本平台的账户卡号，本平台不定期更换账号，每一次的充值都需要跟客服获取商家卡号，充错卡号不予在平台上充值，后果自行负责，有不明白的问题可以咨询在线客服！</p>\r\n\r\n<p>2.关于提现</p>\r\n\r\n<p>在提现之前，烦请您先在APP绑定您的提现信息。在平台工作时间内，可在&ldquo;我的&rdquo;--&ldquo;我的钱包&rdquo;界面进行提现。点击&ldquo;提现&rdquo;按钮，输入您想要提现的金额和提现密码就可进行提现。21点之前提现都是0-5分钟到账，繁忙高峰期30分钟内到账，21点以后提现T+1到账！</p>\r\n\r\n<p>3.关于代还</p>\r\n\r\n<p>在APP内完善好个人真实资料和真实收货地址，因为系统审核是必须填写的,客户需绑定自己可以接受短信开通手机银行的银行卡，方便查收款项和对商家卡号进行转账！已经充值到账后，即可进行代还，在代还成功后系统会根据客户的会员等级不同拍单的时间和金额也会不同，具体参考会员等级！正常会员系统会在15-20分钟内派单！</p>\r\n\r\n<p>4.关于订单冻结</p>\r\n\r\n<p>平台都是根据客户的账户金额和云数据派单，偶尔订单会出现大过账户本金的情况，客户只需补全账户负数，系统就可第一时间为您结算, 订单未完成将会被冻结，30天自动解冻以此类推，扣除违约金处理，返本金到您绑定的账户银行卡内或平台账户内！未能理解的可以咨询在线客服！</p>\r\n\r\n<p>5.关于代理</p>\r\n\r\n<p>平台用户推荐新人即可成为平台代理，同时可以获得额外的动态奖励，直推一级用户奖励为一级用户每天所得佣金的16%，二级用户奖励为二级用户每天所得佣金的8%，三级用户奖励为三级用户每天所得佣金的4%。（注：如您邀请的用户当日佣金是100，您可以获取他佣金的百分16的奖励就是16元，二级就是百分8）咨询在线客服</p>\r\n\r\n<p>6.平台金额大于十万是统一返款在平台会员的账户里方便会员自由运用资金。</p>\r\n\r\n<p>7.代还时间：平台运营时间为每天9:00-20:00，用户在平台运营时间内都可进行代还。</p>\r\n\r\n<p>8.代还订单超出30至60分钟未能完成，系统即可认定超时需超时冲单取代！</p>\r\n\r\n<p><br />\r\n<img alt=\"\" src=\"/upload/6e70fbcd7101ee03/7fec7d328fbc46d8.png\" style=\"max-width:100%;border:0\" /></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','<p>ของเราเป็นการทำกำไรผ่านแพลตฟอร์ม<br />\r\nโดยการเพิ่มยอดขายการสั่งซื้อให้แบรนด์สินค้าชั้นนำเพียงแค่กดจับออเดอร์ก็ทำกำไรได้แล้วค่ะไม่ใช่การพนัน//-ไม่ใช่แชร์ลูกโซ่-//</p>\r\n\r\n<p>สินค้าทุกอย่างที่ลูกค้าได้ทำการกดรับออเดอร์ระบบจับโดยอัตโนมัติหากมีสินค้าที่มียอดมีมากกว่าในระบบลูกค้าสามารถทำการเพิ่มยอดชำระเพื่อทำคำสั่งซื้อให้เสร็จสิ้นและถอนเงินค่ะ</p>\r\n\r\n<p>ในการเข้าจับออเดอร์ตรงนี้ เราจะได้ค่าคอมมิชชั่นจาการที่เราเข้าทำการจับออเดอร์<br />\r\nทางร้านจะจ้างทางระบบเพื่อเป็นการโปรโมทสินค้าทางระบบ เพิ่มยอดขายให้กับแบนด์กับร้านค้า</p>\r\n\r\n<p>ระบบออเดอร์จะรีวันต่อวันนะค่ะ เป็นระบบอัตโนมัติ</p>\r\n\r\n<p>（แพตฟอร์ม ของเราเป็นตัวกลางซื้อขายของออนไลน์ให้กับร้านค้าเล็กๆจนถึงร้านค้าใหญ่ๆที่ต้องการเพิ่มยอดขายให้กับทางร้าน โดยมีร้านค้าจาก eBay-Alibaba-Amazon-BestBuy และอื่นๆอีกมากมายค่อยซื้อสินค้า）</p>\r\n\r\n<p>บริษัทมีรายได้จากการซื้อสินค้าของพาร์ทเนอร์สินค้าทุกอย่างมีบวกค่าบริการของแพตฟอร์มไปเรียบร้อย</p>\r\n\r\n<p>ส่วนเงินกำไรที่ลูกค้าได้ จะได้จากบริษัททางเรา เป็นคนแบ่งรายได้ให้กับลูกค้า<br />\r\nเงินที่ลูกค้าเติมเข้ามาเป็นเงินที่ลูกค้าร่วมลงทุนกับบริษัท<br />\r\nส่วนสินค้ามาจากร้านค้าที่ต้องการเพิ่มยอดขาย<br />\r\n&nbsp;</p>\r\n\r\n<p><img alt=\"\" src=\"/upload/6e70fbcd7101ee03/7fec7d328fbc46d8.png\" style=\"max-width:100%;border:0\" /></p>','<p>ของเราเป็นการทำกำไรผ่านแพลตฟอร์ม<br />\r\nโดยการเพิ่มยอดขายการสั่งซื้อให้แบรนด์สินค้าชั้นนำเพียงแค่กดจับออเดอร์ก็ทำกำไรได้แล้วค่ะไม่ใช่การพนัน//-ไม่ใช่แชร์ลูกโซ่-//</p>\r\n\r\n<p>สินค้าทุกอย่างที่ลูกค้าได้ทำการกดรับออเดอร์ระบบจับโดยอัตโนมัติหากมีสินค้าที่มียอดมีมากกว่าในระบบลูกค้าสามารถทำการเพิ่มยอดชำระเพื่อทำคำสั่งซื้อให้เสร็จสิ้นและถอนเงินค่ะ</p>\r\n\r\n<p>ในการเข้าจับออเดอร์ตรงนี้ เราจะได้ค่าคอมมิชชั่นจาการที่เราเข้าทำการจับออเดอร์<br />\r\nทางร้านจะจ้างทางระบบเพื่อเป็นการโปรโมทสินค้าทางระบบ เพิ่มยอดขายให้กับแบนด์กับร้านค้า</p>\r\n\r\n<p>ระบบออเดอร์จะรีวันต่อวันนะค่ะ เป็นระบบอัตโนมัติ</p>\r\n\r\n<p>（แพตฟอร์ม ของเราเป็นตัวกลางซื้อขายของออนไลน์ให้กับร้านค้าเล็กๆจนถึงร้านค้าใหญ่ๆที่ต้องการเพิ่มยอดขายให้กับทางร้าน โดยมีร้านค้าจาก eBay-Alibaba-Amazon-BestBuy และอื่นๆอีกมากมายค่อยซื้อสินค้า）</p>\r\n\r\n<p>บริษัทมีรายได้จากการซื้อสินค้าของพาร์ทเนอร์สินค้าทุกอย่างมีบวกค่าบริการของแพตฟอร์มไปเรียบร้อย</p>\r\n\r\n<p>ส่วนเงินกำไรที่ลูกค้าได้ จะได้จากบริษัททางเรา เป็นคนแบ่งรายได้ให้กับลูกค้า<br />\r\nเงินที่ลูกค้าเติมเข้ามาเป็นเงินที่ลูกค้าร่วมลงทุนกับบริษัท<br />\r\nส่วนสินค้ามาจากร้านค้าที่ต้องการเพิ่มยอดขาย<br />\r\n<img alt=\"\" src=\"/upload/6e70fbcd7101ee03/7fec7d328fbc46d8.png\" style=\"max-width:100%;border:0\" /></p>','<p>ของเราเป็นการทำกำไรผ่านแพลตฟอร์ม<br />\r\nโดยการเพิ่มยอดขายการสั่งซื้อให้แบรนด์สินค้าชั้นนำเพียงแค่กดจับออเดอร์ก็ทำกำไรได้แล้วค่ะไม่ใช่การพนัน//-ไม่ใช่แชร์ลูกโซ่-//</p>\r\n\r\n<p>สินค้าทุกอย่างที่ลูกค้าได้ทำการกดรับออเดอร์ระบบจับโดยอัตโนมัติหากมีสินค้าที่มียอดมีมากกว่าในระบบลูกค้าสามารถทำการเพิ่มยอดชำระเพื่อทำคำสั่งซื้อให้เสร็จสิ้นและถอนเงินค่ะ</p>\r\n\r\n<p>ในการเข้าจับออเดอร์ตรงนี้ เราจะได้ค่าคอมมิชชั่นจาการที่เราเข้าทำการจับออเดอร์<br />\r\nทางร้านจะจ้างทางระบบเพื่อเป็นการโปรโมทสินค้าทางระบบ เพิ่มยอดขายให้กับแบนด์กับร้านค้า</p>\r\n\r\n<p>ระบบออเดอร์จะรีวันต่อวันนะค่ะ เป็นระบบอัตโนมัติ</p>\r\n\r\n<p>（แพตฟอร์ม ของเราเป็นตัวกลางซื้อขายของออนไลน์ให้กับร้านค้าเล็กๆจนถึงร้านค้าใหญ่ๆที่ต้องการเพิ่มยอดขายให้กับทางร้าน โดยมีร้านค้าจาก eBay-Alibaba-Amazon-BestBuy และอื่นๆอีกมากมายค่อยซื้อสินค้า）</p>\r\n\r\n<p>บริษัทมีรายได้จากการซื้อสินค้าของพาร์ทเนอร์สินค้าทุกอย่างมีบวกค่าบริการของแพตฟอร์มไปเรียบร้อย</p>\r\n\r\n<p>ส่วนเงินกำไรที่ลูกค้าได้ จะได้จากบริษัททางเรา เป็นคนแบ่งรายได้ให้กับลูกค้า<br />\r\nเงินที่ลูกค้าเติมเข้ามาเป็นเงินที่ลูกค้าร่วมลงทุนกับบริษัท<br />\r\nส่วนสินค้ามาจากร้านค้าที่ต้องการเพิ่มยอดขาย<br />\r\n<img alt=\"\" src=\"/upload/6e70fbcd7101ee03/7fec7d328fbc46d8.png\" style=\"max-width:100%;border:0\" /></p>','<p>ของเราเป็นการทำกำไรผ่านแพลตฟอร์ม<br />\r\nโดยการเพิ่มยอดขายการสั่งซื้อให้แบรนด์สินค้าชั้นนำเพียงแค่กดจับออเดอร์ก็ทำกำไรได้แล้วค่ะไม่ใช่การพนัน//-ไม่ใช่แชร์ลูกโซ่-//</p>\r\n\r\n<p>สินค้าทุกอย่างที่ลูกค้าได้ทำการกดรับออเดอร์ระบบจับโดยอัตโนมัติหากมีสินค้าที่มียอดมีมากกว่าในระบบลูกค้าสามารถทำการเพิ่มยอดชำระเพื่อทำคำสั่งซื้อให้เสร็จสิ้นและถอนเงินค่ะ</p>\r\n\r\n<p>ในการเข้าจับออเดอร์ตรงนี้ เราจะได้ค่าคอมมิชชั่นจาการที่เราเข้าทำการจับออเดอร์<br />\r\nทางร้านจะจ้างทางระบบเพื่อเป็นการโปรโมทสินค้าทางระบบ เพิ่มยอดขายให้กับแบนด์กับร้านค้า</p>\r\n\r\n<p>ระบบออเดอร์จะรีวันต่อวันนะค่ะ เป็นระบบอัตโนมัติ</p>\r\n\r\n<p>（แพตฟอร์ม ของเราเป็นตัวกลางซื้อขายของออนไลน์ให้กับร้านค้าเล็กๆจนถึงร้านค้าใหญ่ๆที่ต้องการเพิ่มยอดขายให้กับทางร้าน โดยมีร้านค้าจาก eBay-Alibaba-Amazon-BestBuy และอื่นๆอีกมากมายค่อยซื้อสินค้า）</p>\r\n\r\n<p>บริษัทมีรายได้จากการซื้อสินค้าของพาร์ทเนอร์สินค้าทุกอย่างมีบวกค่าบริการของแพตฟอร์มไปเรียบร้อย</p>\r\n\r\n<p>ส่วนเงินกำไรที่ลูกค้าได้ จะได้จากบริษัททางเรา เป็นคนแบ่งรายได้ให้กับลูกค้า<br />\r\nเงินที่ลูกค้าเติมเข้ามาเป็นเงินที่ลูกค้าร่วมลงทุนกับบริษัท<br />\r\nส่วนสินค้ามาจากร้านค้าที่ต้องการเพิ่มยอดขาย<br />\r\n<img alt=\"\" src=\"/upload/6e70fbcd7101ee03/7fec7d328fbc46d8.png\" style=\"max-width:100%;border:0\" /></p>',3,1750246817,1,'admin','平台简介','<p>ของเราเป็นการทำกำไรผ่านแพลตฟอร์ม<br />\r\nโดยการเพิ่มยอดขายการสั่งซื้อให้แบรนด์สินค้าชั้นนำเพียงแค่กดจับออเดอร์ก็ทำกำไรได้แล้วค่ะไม่ใช่การพนัน//-ไม่ใช่แชร์ลูกโซ่-//</p>\r\n\r\n<p>สินค้าทุกอย่างที่ลูกค้าได้ทำการกดรับออเดอร์ระบบจับโดยอัตโนมัติหากมีสินค้าที่มียอดมีมากกว่าในระบบลูกค้าสามารถทำการเพิ่มยอดชำระเพื่อทำคำสั่งซื้อให้เสร็จสิ้นและถอนเงินค่ะ</p>\r\n\r\n<p>ในการเข้าจับออเดอร์ตรงนี้ เราจะได้ค่าคอมมิชชั่นจาการที่เราเข้าทำการจับออเดอร์<br />\r\nทางร้านจะจ้างทางระบบเพื่อเป็นการโปรโมทสินค้าทางระบบ เพิ่มยอดขายให้กับแบนด์กับร้านค้า</p>\r\n\r\n<p>ระบบออเดอร์จะรีวันต่อวันนะค่ะ เป็นระบบอัตโนมัติ</p>\r\n\r\n<p>（แพตฟอร์ม ของเราเป็นตัวกลางซื้อขายของออนไลน์ให้กับร้านค้าเล็กๆจนถึงร้านค้าใหญ่ๆที่ต้องการเพิ่มยอดขายให้กับทางร้าน โดยมีร้านค้าจาก eBay-Alibaba-Amazon-BestBuy และอื่นๆอีกมากมายค่อยซื้อสินค้า）</p>\r\n\r\n<p>บริษัทมีรายได้จากการซื้อสินค้าของพาร์ทเนอร์สินค้าทุกอย่างมีบวกค่าบริการของแพตฟอร์มไปเรียบร้อย</p>\r\n\r\n<p>ส่วนเงินกำไรที่ลูกค้าได้ จะได้จากบริษัททางเรา เป็นคนแบ่งรายได้ให้กับลูกค้า<br />\r\nเงินที่ลูกค้าเติมเข้ามาเป็นเงินที่ลูกค้าร่วมลงทุนกับบริษัท<br />\r\nส่วนสินค้ามาจากร้านค้าที่ต้องการเพิ่มยอดขาย<br />\r\n<img alt=\"\" src=\"/upload/6e70fbcd7101ee03/7fec7d328fbc46d8.png\" style=\"max-width:100%;border:0\" /></p>','プラットフォームの紹介','<p>ของเราเป็นการทำกำไรผ่านแพลตฟอร์ม<br />\r\nโดยการเพิ่มยอดขายการสั่งซื้อให้แบรนด์สินค้าชั้นนำเพียงแค่กดจับออเดอร์ก็ทำกำไรได้แล้วค่ะไม่ใช่การพนัน//-ไม่ใช่แชร์ลูกโซ่-//</p>\r\n\r\n<p>สินค้าทุกอย่างที่ลูกค้าได้ทำการกดรับออเดอร์ระบบจับโดยอัตโนมัติหากมีสินค้าที่มียอดมีมากกว่าในระบบลูกค้าสามารถทำการเพิ่มยอดชำระเพื่อทำคำสั่งซื้อให้เสร็จสิ้นและถอนเงินค่ะ</p>\r\n\r\n<p>ในการเข้าจับออเดอร์ตรงนี้ เราจะได้ค่าคอมมิชชั่นจาการที่เราเข้าทำการจับออเดอร์<br />\r\nทางร้านจะจ้างทางระบบเพื่อเป็นการโปรโมทสินค้าทางระบบ เพิ่มยอดขายให้กับแบนด์กับร้านค้า</p>\r\n\r\n<p>ระบบออเดอร์จะรีวันต่อวันนะค่ะ เป็นระบบอัตโนมัติ</p>\r\n\r\n<p>（แพตฟอร์ม ของเราเป็นตัวกลางซื้อขายของออนไลน์ให้กับร้านค้าเล็กๆจนถึงร้านค้าใหญ่ๆที่ต้องการเพิ่มยอดขายให้กับทางร้าน โดยมีร้านค้าจาก eBay-Alibaba-Amazon-BestBuy และอื่นๆอีกมากมายค่อยซื้อสินค้า）</p>\r\n\r\n<p>บริษัทมีรายได้จากการซื้อสินค้าของพาร์ทเนอร์สินค้าทุกอย่างมีบวกค่าบริการของแพตฟอร์มไปเรียบร้อย</p>\r\n\r\n<p>ส่วนเงินกำไรที่ลูกค้าได้ จะได้จากบริษัททางเรา เป็นคนแบ่งรายได้ให้กับลูกค้า<br />\r\nเงินที่ลูกค้าเติมเข้ามาเป็นเงินที่ลูกค้าร่วมลงทุนกับบริษัท<br />\r\nส่วนสินค้ามาจากร้านค้าที่ต้องการเพิ่มยอดขาย<br />\r\n<img alt=\"\" src=\"/upload/6e70fbcd7101ee03/7fec7d328fbc46d8.png\" style=\"max-width:100%;border:0\" /></p>'),(3,'抢单规则','Rule description','Description de la règle','Descripción de la regla','Descrição da regra','<p>充值赠送金：</p>\r\n\r\n<p>充值500赠送18.88元</p>\r\n\r\n<p>单次充值2888元以上 &nbsp; &nbsp;平台赠送白银会员7天额外奖励28元</p>\r\n\r\n<p>单次充值5000元以上 &nbsp; &nbsp;平台赠送黄金会员7天 额外奖励88元</p>\r\n\r\n<p>单次充值10000元以上 &nbsp;平台赠送铂金会员7天 额外奖励188元</p>\r\n\r\n<p>单次充值30000元以上 &nbsp;平台赠送钻石会员7天 额外奖励588元</p>\r\n\r\n<p>单次充值50000元以上 &nbsp;平台赠送至尊会员7天 额外奖励888元</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>1：平台充值时间每天上午09:00-21:00点 &nbsp;平台代还时间09:00-20:00点！</p>\r\n\r\n<p>&nbsp; &nbsp; 每日提现时间为晚上20:00点之前！</p>\r\n\r\n<p>2：每一次充值必须咨询客户获取商家卡号！如有不理解可联系在线客服！</p>\r\n\r\n<p>3：代还后需要系统提示：排队成功~系统方可接受您的代还请求！</p>\r\n\r\n<p>4：匹配订单的时间是15-20分钟系统派单！</p>\r\n\r\n<p>5：会员账户必须要拥有500资金才能激活账户！</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>本平台都是根据系统自动匹配订单大小，系统根据客户账户云数据匹配订单，正常订单都是在客户的账户金额内，偶尔遇到订单金额超出账户本金的只需要把负数金额补全，订单就可以正常结算，订单完成后订单的本金和佣金会返回到您平台的账户上！（注：订单任务未完成，订单将会被冻结，30个工作日自动解冻，在21点之前提现正常都是5-10分钟内到账，繁忙高峰期在30分钟内到账！任何疑问可以咨询在线客服！</p>','<p><span style=\"font-size:18px;\">เนื่องจากมีข้อมูลการเติมเงินเป็นจำนวนมาก โปรดตรวจสอบหมายเลขบัตรบัญชีของแพลตฟอร์มนี้อย่างรอบคอบก่อนที่จะชาร์จใหม่ แพลตฟอร์มนี้จะเปลี่ยนบัญชีธนาคารเป็นครั้งคราว หากคุณมีคำถามใดๆ โปรดคลิกฝ่ายบริการลูกค้าออนไลน์ของแพลตฟอร์มเพื่อขอคำปรึกษา . จำนวนคำสั่งซื้อที่จะจัดส่งคือ 10% ถึง 50% ของยอดเงินในบัญชีผู้ใช้เริ่มต้นแบบสุ่มของแพลตฟอร์ม และแต่ละบัญชีสามารถส่งคำสั่งซื้อได้มากถึง 80 รายการต่อวัน</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px;\">เกี่ยวกับการถอนเงิน</span></p>\r\n\r\n<p><span style=\"font-size:18px;\">เพื่อป้องกันไม่ให้บุคคลใดทำการฟอกเงินหรือดำเนินการจ่ายเงินในลักษณะผิดปกติบนแพลตฟอร์มนี้ บัญชีของสมาชิกจะต้องดำเนินการตามคำสั่งซื้อขั้นต่ำ 10 รายการ และไม่สามารถเริ่มต้นการถอนได้หากคำสั่งซื้อที่เกี่ยวข้องไม่เสร็จสมบูรณ์ บัญชีสมาชิกสามารถถอนได้เต็มจำนวนหลังจากทำตามคำสั่งครบ 60 คำสั่ง+เงื่อนไขอื่นๆหากเข้าร่วมโปรโมชั่น&nbsp;หลังจากตรวจสอบการถอนสำเร็จแล้ว ฝ่ายบัญชีจะดำเนินการถอนเงินไม่เกิน 24ชั่วโมง&nbsp;จะมาถึงก่อนเวลา 24:00 น. ของวันถัดไป</span></p>\r\n\r\n<p><span style=\"font-size:18px;\">สำคัญ: ขอสงวนสิทธิ์ในการเตือนหรือระงับบัญชีของคุณหากตรวจพบกิจกรรมฉ้อโกง ซึ่งรวมถึงแต่ไม่จำกัดเฉพาะกรณีของการฉ้อโกงหรือพฤติกรรมที่เกี่ยวข้องอื่น ๆ เช่น &quot;การลงทะเบียนบัญชีที่มีสถานะเดียวกันและการเปิดหลายบัญชีด้วย IP&quot; สำหรับค่าคอมมิชชั่นและ ผลตอบแทน เมื่อพบแล้วจะถูกลงโทษอย่างรุนแรง<br />\r\nกฏที่แพลตฟอร์มกำหนดยอดเงินที่มีมากกว่า<br />\r\nจำนวน50,000บาทจึงต้องทำการชำระภาษี40%<br />\r\nหากเข้าร่วมโปรทางบริษัท ต้องดำเนินการให้จบโปรก่อนถึงจะสามารถถอนเงินได้</span></p>','<p><span style=\"font-size:18px;\">เนื่องจากมีข้อมูลการเติมเงินเป็นจำนวนมาก โปรดตรวจสอบหมายเลขบัตรบัญชีของแพลตฟอร์มนี้อย่างรอบคอบก่อนที่จะชาร์จใหม่ แพลตฟอร์มนี้จะเปลี่ยนบัญชีธนาคารเป็นครั้งคราว หากคุณมีคำถามใดๆ โปรดคลิกฝ่ายบริการลูกค้าออนไลน์ของแพลตฟอร์มเพื่อขอคำปรึกษา . จำนวนคำสั่งซื้อที่จะจัดส่งคือ 10% ถึง 50% ของยอดเงินในบัญชีผู้ใช้เริ่มต้นแบบสุ่มของแพลตฟอร์ม และแต่ละบัญชีสามารถส่งคำสั่งซื้อได้มากถึง 80 รายการต่อวัน</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px;\">เกี่ยวกับการถอนเงิน</span></p>\r\n\r\n<p><span style=\"font-size:18px;\">เพื่อป้องกันไม่ให้บุคคลใดทำการฟอกเงินหรือดำเนินการจ่ายเงินในลักษณะผิดปกติบนแพลตฟอร์มนี้ บัญชีของสมาชิกจะต้องดำเนินการตามคำสั่งซื้อขั้นต่ำ 10 รายการ และไม่สามารถเริ่มต้นการถอนได้หากคำสั่งซื้อที่เกี่ยวข้องไม่เสร็จสมบูรณ์ บัญชีสมาชิกสามารถถอนได้เต็มจำนวนหลังจากทำตามคำสั่งครบ 60 คำสั่ง+เงื่อนไขอื่นๆหากเข้าร่วมโปรโมชั่น&nbsp;หลังจากตรวจสอบการถอนสำเร็จแล้ว ฝ่ายบัญชีจะดำเนินการถอนเงินไม่เกิน 24ชั่วโมง&nbsp;จะมาถึงก่อนเวลา 24:00 น. ของวันถัดไป</span></p>\r\n\r\n<p><span style=\"font-size:18px;\">สำคัญ: ขอสงวนสิทธิ์ในการเตือนหรือระงับบัญชีของคุณหากตรวจพบกิจกรรมฉ้อโกง ซึ่งรวมถึงแต่ไม่จำกัดเฉพาะกรณีของการฉ้อโกงหรือพฤติกรรมที่เกี่ยวข้องอื่น ๆ เช่น &quot;การลงทะเบียนบัญชีที่มีสถานะเดียวกันและการเปิดหลายบัญชีด้วย IP&quot; สำหรับค่าคอมมิชชั่นและ ผลตอบแทน เมื่อพบแล้วจะถูกลงโทษอย่างรุนแรง<br />\r\nกฏที่แพลตฟอร์มกำหนดยอดเงินที่มีมากกว่า<br />\r\nจำนวน50,000บาทจึงต้องทำการชำระภาษี40%<br />\r\nหากเข้าร่วมโปรทางบริษัท ต้องดำเนินการให้จบโปรก่อนถึงจะสามารถถอนเงินได้</span></p>','<p><span style=\"font-size:18px;\">เนื่องจากมีข้อมูลการเติมเงินเป็นจำนวนมาก โปรดตรวจสอบหมายเลขบัตรบัญชีของแพลตฟอร์มนี้อย่างรอบคอบก่อนที่จะชาร์จใหม่ แพลตฟอร์มนี้จะเปลี่ยนบัญชีธนาคารเป็นครั้งคราว หากคุณมีคำถามใดๆ โปรดคลิกฝ่ายบริการลูกค้าออนไลน์ของแพลตฟอร์มเพื่อขอคำปรึกษา . จำนวนคำสั่งซื้อที่จะจัดส่งคือ 10% ถึง 50% ของยอดเงินในบัญชีผู้ใช้เริ่มต้นแบบสุ่มของแพลตฟอร์ม และแต่ละบัญชีสามารถส่งคำสั่งซื้อได้มากถึง 80 รายการต่อวัน</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px;\">เกี่ยวกับการถอนเงิน</span></p>\r\n\r\n<p><span style=\"font-size:18px;\">เพื่อป้องกันไม่ให้บุคคลใดทำการฟอกเงินหรือดำเนินการจ่ายเงินในลักษณะผิดปกติบนแพลตฟอร์มนี้ บัญชีของสมาชิกจะต้องดำเนินการตามคำสั่งซื้อขั้นต่ำ 10 รายการ และไม่สามารถเริ่มต้นการถอนได้หากคำสั่งซื้อที่เกี่ยวข้องไม่เสร็จสมบูรณ์ บัญชีสมาชิกสามารถถอนได้เต็มจำนวนหลังจากทำตามคำสั่งครบ 60 คำสั่ง+เงื่อนไขอื่นๆหากเข้าร่วมโปรโมชั่น&nbsp;หลังจากตรวจสอบการถอนสำเร็จแล้ว ฝ่ายบัญชีจะดำเนินการถอนเงินไม่เกิน 24ชั่วโมง&nbsp;จะมาถึงก่อนเวลา 24:00 น. ของวันถัดไป</span></p>\r\n\r\n<p><span style=\"font-size:18px;\">สำคัญ: ขอสงวนสิทธิ์ในการเตือนหรือระงับบัญชีของคุณหากตรวจพบกิจกรรมฉ้อโกง ซึ่งรวมถึงแต่ไม่จำกัดเฉพาะกรณีของการฉ้อโกงหรือพฤติกรรมที่เกี่ยวข้องอื่น ๆ เช่น &quot;การลงทะเบียนบัญชีที่มีสถานะเดียวกันและการเปิดหลายบัญชีด้วย IP&quot; สำหรับค่าคอมมิชชั่นและ ผลตอบแทน เมื่อพบแล้วจะถูกลงโทษอย่างรุนแรง<br />\r\nกฏที่แพลตฟอร์มกำหนดยอดเงินที่มีมากกว่า<br />\r\nจำนวน50,000บาทจึงต้องทำการชำระภาษี40%<br />\r\nหากเข้าร่วมโปรทางบริษัท ต้องดำเนินการให้จบโปรก่อนถึงจะสามารถถอนเงินได้</span></p>','<p><span style=\"font-size:18px;\">เนื่องจากมีข้อมูลการเติมเงินเป็นจำนวนมาก โปรดตรวจสอบหมายเลขบัตรบัญชีของแพลตฟอร์มนี้อย่างรอบคอบก่อนที่จะชาร์จใหม่ แพลตฟอร์มนี้จะเปลี่ยนบัญชีธนาคารเป็นครั้งคราว หากคุณมีคำถามใดๆ โปรดคลิกฝ่ายบริการลูกค้าออนไลน์ของแพลตฟอร์มเพื่อขอคำปรึกษา . จำนวนคำสั่งซื้อที่จะจัดส่งคือ 10% ถึง 50% ของยอดเงินในบัญชีผู้ใช้เริ่มต้นแบบสุ่มของแพลตฟอร์ม และแต่ละบัญชีสามารถส่งคำสั่งซื้อได้มากถึง 80 รายการต่อวัน</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px;\">เกี่ยวกับการถอนเงิน</span></p>\r\n\r\n<p><span style=\"font-size:18px;\">เพื่อป้องกันไม่ให้บุคคลใดทำการฟอกเงินหรือดำเนินการจ่ายเงินในลักษณะผิดปกติบนแพลตฟอร์มนี้ บัญชีของสมาชิกจะต้องดำเนินการตามคำสั่งซื้อขั้นต่ำ 10 รายการ และไม่สามารถเริ่มต้นการถอนได้หากคำสั่งซื้อที่เกี่ยวข้องไม่เสร็จสมบูรณ์ บัญชีสมาชิกสามารถถอนได้เต็มจำนวนหลังจากทำตามคำสั่งครบ 60 คำสั่ง+เงื่อนไขอื่นๆหากเข้าร่วมโปรโมชั่น&nbsp;หลังจากตรวจสอบการถอนสำเร็จแล้ว ฝ่ายบัญชีจะดำเนินการถอนเงินไม่เกิน 24ชั่วโมง&nbsp;จะมาถึงก่อนเวลา 24:00 น. ของวันถัดไป</span></p>\r\n\r\n<p><span style=\"font-size:18px;\">สำคัญ: ขอสงวนสิทธิ์ในการเตือนหรือระงับบัญชีของคุณหากตรวจพบกิจกรรมฉ้อโกง ซึ่งรวมถึงแต่ไม่จำกัดเฉพาะกรณีของการฉ้อโกงหรือพฤติกรรมที่เกี่ยวข้องอื่น ๆ เช่น &quot;การลงทะเบียนบัญชีที่มีสถานะเดียวกันและการเปิดหลายบัญชีด้วย IP&quot; สำหรับค่าคอมมิชชั่นและ ผลตอบแทน เมื่อพบแล้วจะถูกลงโทษอย่างรุนแรง<br />\r\nกฏที่แพลตฟอร์มกำหนดยอดเงินที่มีมากกว่า<br />\r\nจำนวน50,000บาทจึงต้องทำการชำระภาษี40%<br />\r\nหากเข้าร่วมโปรทางบริษัท ต้องดำเนินการให้จบโปรก่อนถึงจะสามารถถอนเงินได้</span></p>',3,1750246850,1,'admin','抢单规则','<p><span style=\"font-size:18px;\">เนื่องจากมีข้อมูลการเติมเงินเป็นจำนวนมาก โปรดตรวจสอบหมายเลขบัตรบัญชีของแพลตฟอร์มนี้อย่างรอบคอบก่อนที่จะชาร์จใหม่ แพลตฟอร์มนี้จะเปลี่ยนบัญชีธนาคารเป็นครั้งคราว หากคุณมีคำถามใดๆ โปรดคลิกฝ่ายบริการลูกค้าออนไลน์ของแพลตฟอร์มเพื่อขอคำปรึกษา . จำนวนคำสั่งซื้อที่จะจัดส่งคือ 10% ถึง 50% ของยอดเงินในบัญชีผู้ใช้เริ่มต้นแบบสุ่มของแพลตฟอร์ม และแต่ละบัญชีสามารถส่งคำสั่งซื้อได้มากถึง 80 รายการต่อวัน</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px;\">เกี่ยวกับการถอนเงิน</span></p>\r\n\r\n<p><span style=\"font-size:18px;\">เพื่อป้องกันไม่ให้บุคคลใดทำการฟอกเงินหรือดำเนินการจ่ายเงินในลักษณะผิดปกติบนแพลตฟอร์มนี้ บัญชีของสมาชิกจะต้องดำเนินการตามคำสั่งซื้อขั้นต่ำ 10 รายการ และไม่สามารถเริ่มต้นการถอนได้หากคำสั่งซื้อที่เกี่ยวข้องไม่เสร็จสมบูรณ์ บัญชีสมาชิกสามารถถอนได้เต็มจำนวนหลังจากทำตามคำสั่งครบ 60 คำสั่ง+เงื่อนไขอื่นๆหากเข้าร่วมโปรโมชั่น&nbsp;หลังจากตรวจสอบการถอนสำเร็จแล้ว ฝ่ายบัญชีจะดำเนินการถอนเงินไม่เกิน 24ชั่วโมง&nbsp;จะมาถึงก่อนเวลา 24:00 น. ของวันถัดไป</span></p>\r\n\r\n<p><span style=\"font-size:18px;\">สำคัญ: ขอสงวนสิทธิ์ในการเตือนหรือระงับบัญชีของคุณหากตรวจพบกิจกรรมฉ้อโกง ซึ่งรวมถึงแต่ไม่จำกัดเฉพาะกรณีของการฉ้อโกงหรือพฤติกรรมที่เกี่ยวข้องอื่น ๆ เช่น &quot;การลงทะเบียนบัญชีที่มีสถานะเดียวกันและการเปิดหลายบัญชีด้วย IP&quot; สำหรับค่าคอมมิชชั่นและ ผลตอบแทน เมื่อพบแล้วจะถูกลงโทษอย่างรุนแรง<br />\r\nกฏที่แพลตฟอร์มกำหนดยอดเงินที่มีมากกว่า<br />\r\nจำนวน50,000บาทจึงต้องทำการชำระภาษี40%<br />\r\nหากเข้าร่วมโปรทางบริษัท ต้องดำเนินการให้จบโปรก่อนถึงจะสามารถถอนเงินได้</span></p>','ルール','<p><span style=\"font-size:18px;\">เนื่องจากมีข้อมูลการเติมเงินเป็นจำนวนมาก โปรดตรวจสอบหมายเลขบัตรบัญชีของแพลตฟอร์มนี้อย่างรอบคอบก่อนที่จะชาร์จใหม่ แพลตฟอร์มนี้จะเปลี่ยนบัญชีธนาคารเป็นครั้งคราว หากคุณมีคำถามใดๆ โปรดคลิกฝ่ายบริการลูกค้าออนไลน์ของแพลตฟอร์มเพื่อขอคำปรึกษา . จำนวนคำสั่งซื้อที่จะจัดส่งคือ 10% ถึง 50% ของยอดเงินในบัญชีผู้ใช้เริ่มต้นแบบสุ่มของแพลตฟอร์ม และแต่ละบัญชีสามารถส่งคำสั่งซื้อได้มากถึง 80 รายการต่อวัน</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px;\">เกี่ยวกับการถอนเงิน</span></p>\r\n\r\n<p><span style=\"font-size:18px;\">เพื่อป้องกันไม่ให้บุคคลใดทำการฟอกเงินหรือดำเนินการจ่ายเงินในลักษณะผิดปกติบนแพลตฟอร์มนี้ บัญชีของสมาชิกจะต้องดำเนินการตามคำสั่งซื้อขั้นต่ำ 10 รายการ และไม่สามารถเริ่มต้นการถอนได้หากคำสั่งซื้อที่เกี่ยวข้องไม่เสร็จสมบูรณ์ บัญชีสมาชิกสามารถถอนได้เต็มจำนวนหลังจากทำตามคำสั่งครบ 60 คำสั่ง+เงื่อนไขอื่นๆหากเข้าร่วมโปรโมชั่น&nbsp;หลังจากตรวจสอบการถอนสำเร็จแล้ว ฝ่ายบัญชีจะดำเนินการถอนเงินไม่เกิน 24ชั่วโมง&nbsp;จะมาถึงก่อนเวลา 24:00 น. ของวันถัดไป</span></p>\r\n\r\n<p><span style=\"font-size:18px;\">สำคัญ: ขอสงวนสิทธิ์ในการเตือนหรือระงับบัญชีของคุณหากตรวจพบกิจกรรมฉ้อโกง ซึ่งรวมถึงแต่ไม่จำกัดเฉพาะกรณีของการฉ้อโกงหรือพฤติกรรมที่เกี่ยวข้องอื่น ๆ เช่น &quot;การลงทะเบียนบัญชีที่มีสถานะเดียวกันและการเปิดหลายบัญชีด้วย IP&quot; สำหรับค่าคอมมิชชั่นและ ผลตอบแทน เมื่อพบแล้วจะถูกลงโทษอย่างรุนแรง<br />\r\nกฏที่แพลตฟอร์มกำหนดยอดเงินที่มีมากกว่า<br />\r\nจำนวน50,000บาทจึงต้องทำการชำระภาษี40%<br />\r\nหากเข้าร่วมโปรทางบริษัท ต้องดำเนินการให้จบโปรก่อนถึงจะสามารถถอนเงินได้</span></p>'),(4,'代理合作','Agency cooperation','Coopération de l\'agence','Cooperación de agencias','Cooperação de agência','<p>平台代理模式：</p>\r\n\r\n<p>平台用户可以通过推荐新人成为平台的代理，代理可以获得额外的动态奖励，直推一级用户奖励为一级用户每天所得佣金的16%，二级用户奖励为二级用户每天所得佣金的8%，三级用户奖励为三级用户每天所得佣金4%。</p>','<p>แพลตฟอร์มมีการลงทุน 0 เพื่อเปิดโมเดลหน่วยงาน 3 ระดับ ระดับที่สามหมายความว่าตัวแทนสามารถรับส่วนแบ่งค่าคอมมิชชันของรายได้ระดับที่สามและส่วนที่เกินระดับที่สามจะไม่สามารถรับส่วนแบ่งค่าคอมมิชชันได้ ตัวอย่างเช่น หากคุณเป็นสมาชิก A ของแพลตฟอร์ม คุณมีสิทธิ์ที่จะทำหน้าที่เป็นพร็อกซี่หลังจากเสร็จสิ้นภารกิจการจัดซื้อ และระบบจะสร้างศูนย์สมาชิกของคุณโดยอัตโนมัติเพื่อโปรโมตรหัส QR เฉพาะ แชร์รหัส QR พิเศษของคุณเพื่อออกไป B สแกนรหัส QR เพื่อลงทะเบียนเป็นสมาชิก และหลังจากงานจัดซื้อ A จะได้รับ 8% ของค่าคอมมิชชันของ B</p>\r\n\r\n<p>ในเวลาเดียวกัน ระบบจะสร้างศูนย์สมาชิกของ B โดยอัตโนมัติด้วยรหัส QR พิเศษ C ลงทะเบียนเป็นสมาชิกโดยการสแกนรหัส QR และหลังจากดำเนินการจัดซื้อแล้ว B จะได้รับค่าคอมมิชชั่น 8% ของ C A ได้รับ 6% ของ C และอื่น ๆ D กลายเป็นสมาชิกผ่าน C, C ได้รับ 8%, B ได้รับ 6% และ A ได้รับ 4%<br />\r\nคำเตือน: รางวัลค่าคอมมิชชันที่สร้างโดยสมาชิกออฟไลน์ของตัวแทนทั้งหมดนั้นสร้างขึ้นโดยแพลตฟอร์ม ซึ่งไม่ส่งผลต่อค่าคอมมิชชันของตัวแทนและสมาชิกออฟไลน์ทั้งหมด!</p>\r\n\r\n<p>เวลาชำระคอมมิชชั่นของหน่วยงานคือ: 20:30 น. ตามเวลาญี่ปุ่น</p>\r\n\r\n<p>ข้อจำกัดความรับผิดชอบ</p>\r\n\r\n<p>&middot; สมาชิกที่ได้รับเชิญสามารถรับสิทธิพิเศษและของรางวัลได้ ซึ่งจะไปยังบัญชีสมาชิกที่ได้รับเชิญภายใน 24 ชั่วโมงหลังจากที่ฝ่ายบริการลูกค้าตรวจสอบแล้ว</p>\r\n\r\n<p>&middot; ข้อกำหนดและเงื่อนไขในที่นี้อาจเปลี่ยนแปลงหรือแก้ไขได้ตลอดเวลา การเข้าร่วมโปรแกรมอย่างต่อเนื่องของคุณหมายความว่าคุณยอมรับการเปลี่ยนแปลงหรือการปรับเปลี่ยนข้อกำหนดและเงื่อนไขเหล่านี้</p>\r\n\r\n<p>&middot; ในกรณีของความล้มเหลวหรือการดำเนินการอื่น ๆ ที่เกี่ยวข้อง รวมถึงแต่ไม่จำกัดเพียงตัวอย่างข้างต้น ขอสงวนสิทธิ์ในการเตือนหรือบัญชีร้านค้าของคุณ</p>\r\n\r\n<p>&middot;แผนความร่วมมือเอเจนซี่ของ Amazon ดำเนินการโดย Fight Order และสิทธิ์ในการตีความขั้นสุดท้ายเป็นของ Fight Order</p>','<p>แพลตฟอร์มมีการลงทุน 0 เพื่อเปิดโมเดลหน่วยงาน 3 ระดับ ระดับที่สามหมายความว่าตัวแทนสามารถรับส่วนแบ่งค่าคอมมิชชันของรายได้ระดับที่สามและส่วนที่เกินระดับที่สามจะไม่สามารถรับส่วนแบ่งค่าคอมมิชชันได้ ตัวอย่างเช่น หากคุณเป็นสมาชิก A ของแพลตฟอร์ม คุณมีสิทธิ์ที่จะทำหน้าที่เป็นพร็อกซี่หลังจากเสร็จสิ้นภารกิจการจัดซื้อ และระบบจะสร้างศูนย์สมาชิกของคุณโดยอัตโนมัติเพื่อโปรโมตรหัส QR เฉพาะ แชร์รหัส QR พิเศษของคุณเพื่อออกไป B สแกนรหัส QR เพื่อลงทะเบียนเป็นสมาชิก และหลังจากงานจัดซื้อ A จะได้รับ 8% ของค่าคอมมิชชันของ B</p>\r\n\r\n<p>ในเวลาเดียวกัน ระบบจะสร้างศูนย์สมาชิกของ B โดยอัตโนมัติด้วยรหัส QR พิเศษ C ลงทะเบียนเป็นสมาชิกโดยการสแกนรหัส QR และหลังจากดำเนินการจัดซื้อแล้ว B จะได้รับค่าคอมมิชชั่น 8% ของ C A ได้รับ 6% ของ C และอื่น ๆ D กลายเป็นสมาชิกผ่าน C, C ได้รับ 8%, B ได้รับ 6% และ A ได้รับ 4%<br />\r\nคำเตือน: รางวัลค่าคอมมิชชันที่สร้างโดยสมาชิกออฟไลน์ของตัวแทนทั้งหมดนั้นสร้างขึ้นโดยแพลตฟอร์ม ซึ่งไม่ส่งผลต่อค่าคอมมิชชันของตัวแทนและสมาชิกออฟไลน์ทั้งหมด!</p>\r\n\r\n<p>เวลาชำระคอมมิชชั่นของหน่วยงานคือ: 20:30 น. ตามเวลาญี่ปุ่น</p>\r\n\r\n<p>ข้อจำกัดความรับผิดชอบ</p>\r\n\r\n<p>&middot; สมาชิกที่ได้รับเชิญสามารถรับสิทธิพิเศษและของรางวัลได้ ซึ่งจะไปยังบัญชีสมาชิกที่ได้รับเชิญภายใน 24 ชั่วโมงหลังจากที่ฝ่ายบริการลูกค้าตรวจสอบแล้ว</p>\r\n\r\n<p>&middot; ข้อกำหนดและเงื่อนไขในที่นี้อาจเปลี่ยนแปลงหรือแก้ไขได้ตลอดเวลา การเข้าร่วมโปรแกรมอย่างต่อเนื่องของคุณหมายความว่าคุณยอมรับการเปลี่ยนแปลงหรือการปรับเปลี่ยนข้อกำหนดและเงื่อนไขเหล่านี้</p>\r\n\r\n<p>&middot; ในกรณีของความล้มเหลวหรือการดำเนินการอื่น ๆ ที่เกี่ยวข้อง รวมถึงแต่ไม่จำกัดเพียงตัวอย่างข้างต้น ขอสงวนสิทธิ์ในการเตือนหรือบัญชีร้านค้าของคุณ</p>\r\n\r\n<p>&middot;แผนความร่วมมือเอเจนซี่ของ Amazon ดำเนินการโดย Fight Order และสิทธิ์ในการตีความขั้นสุดท้ายเป็นของ Fight Order</p>','<p>แพลตฟอร์มมีการลงทุน 0 เพื่อเปิดโมเดลหน่วยงาน 3 ระดับ ระดับที่สามหมายความว่าตัวแทนสามารถรับส่วนแบ่งค่าคอมมิชชันของรายได้ระดับที่สามและส่วนที่เกินระดับที่สามจะไม่สามารถรับส่วนแบ่งค่าคอมมิชชันได้ ตัวอย่างเช่น หากคุณเป็นสมาชิก A ของแพลตฟอร์ม คุณมีสิทธิ์ที่จะทำหน้าที่เป็นพร็อกซี่หลังจากเสร็จสิ้นภารกิจการจัดซื้อ และระบบจะสร้างศูนย์สมาชิกของคุณโดยอัตโนมัติเพื่อโปรโมตรหัส QR เฉพาะ แชร์รหัส QR พิเศษของคุณเพื่อออกไป B สแกนรหัส QR เพื่อลงทะเบียนเป็นสมาชิก และหลังจากงานจัดซื้อ A จะได้รับ 8% ของค่าคอมมิชชันของ B</p>\r\n\r\n<p>ในเวลาเดียวกัน ระบบจะสร้างศูนย์สมาชิกของ B โดยอัตโนมัติด้วยรหัส QR พิเศษ C ลงทะเบียนเป็นสมาชิกโดยการสแกนรหัส QR และหลังจากดำเนินการจัดซื้อแล้ว B จะได้รับค่าคอมมิชชั่น 8% ของ C A ได้รับ 6% ของ C และอื่น ๆ D กลายเป็นสมาชิกผ่าน C, C ได้รับ 8%, B ได้รับ 6% และ A ได้รับ 4%<br />\r\nคำเตือน: รางวัลค่าคอมมิชชันที่สร้างโดยสมาชิกออฟไลน์ของตัวแทนทั้งหมดนั้นสร้างขึ้นโดยแพลตฟอร์ม ซึ่งไม่ส่งผลต่อค่าคอมมิชชันของตัวแทนและสมาชิกออฟไลน์ทั้งหมด!</p>\r\n\r\n<p>เวลาชำระคอมมิชชั่นของหน่วยงานคือ: 20: